const D = { energy: .55, scale: 1, density: .5, speed: 1, wear: .55, hue: 210, x: .5, y: .44, style: 'granite', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A granite sett pavement laid in fan courses (Bogenpflaster) running away to the
// vanishing point. Every sett is an individual domed stone: the crown catches the raking
// light, the sand joint between them takes it away, and two cart ruts are polished down
// the middle where a century of wheels went.
// ONLY BELOW THE HORIZON — everything above stays fully transparent so the bg slot shows
// through. (floor.desert paints an opaque sky over the whole frame and clobbers it.) ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }   // >>> : a >> fold caps the hash at 0.5
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), wr = cl(P.wear,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', wet = sty==='wet', sep = sty==='sepia', moss = sty==='moss';

// ---- camera ----
const vy = cl(P.y,.18,.78)*height, vx = cl(P.x,.05,.95)*width;
const f = u*.92, H0 = 1;
const SL = .085*cl(P.scale,.35,2.4);        // sett size in world units

// ---- perpetual scroll: the pavement streams toward the viewer for ever, so the field can
// never re-phase (new stone arrives continuously). Guarded against a t0 reset. ----
if (S.z == null) S.z = 0;
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z += dt * P.speed * (.14 + .20*K.intensity) * (.55 + .6*en);
const zoff = S.z;

const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
// two light pools drifting on incommensurate rates — broad, live, and they rake the crowns
const l1x = 1.5*Math.sin(tt*.079) + .7*Math.sin(tt*.191+1.3);
const l1z = 3.2 + 1.9*Math.sin(tt*.057+.7) + .9*Math.sin(tt*.149+2.1);
const l2x = -1.8*Math.sin(tt*.107+2.2) - .6*Math.sin(tt*.263);
const l2z = 5.6 + 2.5*Math.sin(tt*.043+1.9) + 1.2*Math.sin(tt*.181+.4);
const glow = (.40+.60*en)*(.55+.5*K.intensity) + bass*.30;

// ---- palette ----
let stoneD, stoneL, jointC, ruttC;
if (bp)        { stoneD=[212,74,14]; stoneL=[190,44,80]; jointC=[214,80,7];  ruttC=[186,50,92]; }
else if (wet)  { stoneD=[Hh+8,34,10]; stoneL=[Hh+4,18,56]; jointC=[Hh+10,40,6]; ruttC=[Hh-4,12,82]; }
else if (sep)  { stoneD=[32,32,22];  stoneL=[38,22,74];  jointC=[28,38,13];  ruttC=[40,16,84]; }
else if (moss) { stoneD=[Hh+6,10,24]; stoneL=[Hh,6,72];   jointC=[104,54,26]; ruttC=[Hh,4,80]; }
else           { stoneD=[Hh,12,21];  stoneL=[Hh-6,7,76]; jointC=[Hh+4,16,11]; ruttC=[Hh-8,5,84]; }
const cSd = hsv(stoneD[0], stoneD[1]/100, stoneD[2]/100);
const cSl = hsv(stoneL[0], stoneL[1]/100, stoneL[2]/100);
const cJt = hsv(jointC[0], jointC[1]/100, jointC[2]/100);
const cRt = hsv(ruttC[0], ruttC[1]/100, ruttC[2]/100);

const BW = 176, BH = Math.max(44, Math.round(BW*height/width));
if (!S.g || S.bk !== BW+'x'+BH){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bk = BW+'x'+BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const AS = SL*4.4;                          // arc-course spacing along the road
const AL = P.alpha/100;
const j0 = Math.max(0, Math.floor((vy/height)*BH));
// --- everything at or above the horizon is fully transparent ---
for (let j=0;j<j0;j++) for (let i=0;i<BW;i++) px[4*(j*BW+i)+3] = 0;

for (let j=j0;j<BH;j++){
  const sy = (j+.5)/BH*height, dy = sy - vy;
  if (dy < .35){ for (let i=0;i<BW;i++) px[4*(j*BW+i)+3] = 0; continue; }
  const Z = f*H0/dy, wz = Z + zoff;
  const far = cl((Z-1.1)/9, 0, 1);
  const det = cl(1 - far*1.05, .04, 1);     // far stone loses its detail into haze
  for (let i=0;i<BW;i++){
    const sx = (i+.5)/BW*width, X = (sx-vx)*Z/f;
    const o = 4*(j*BW+i);
    // ---- Bogenpflaster: nested arcs about centres spaced along the road axis ----
    const kz = Math.round(wz/AS), cz = kz*AS;
    const dx = X, dz = wz - cz;
    const rr = Math.sqrt(dx*dx+dz*dz)+1e-4;
    const aa = Math.atan2(dz, dx);
    const ring = Math.floor(rr/SL);                 // which arc out from the centre
    const arcU = aa*rr/SL;                          // arc length in setts
    const along = Math.floor(arcU);
    const id = ring*97 + along*13 + kz*7 + 5;
    const q = hsh(id, kz*31+ring);                  // per-sett tone lottery
    // local coords inside this sett
    const fr_r = (rr/SL) - ring;
    const fr_a = arcU - along;
    // ---- dome: the sett is a rounded stone, so its crown catches light and its shoulders fall away
    const lx2 = (fr_a-.5)*2, ly2 = (fr_r-.5)*2;
    const rad2 = lx2*lx2 + ly2*ly2;
    const dome = Math.sqrt(cl(1-rad2*.92, 0, 1));
    // ---- joint: the sand gap between stones ----
    const edge = Math.min(Math.min(fr_r, 1-fr_r), Math.min(fr_a, 1-fr_a));
    const jw = .13 + wr*.09;
    const jt = cl(1 - edge/jw, 0, 1);               // 1 deep in the joint, 0 on the crown
    // ---- cart ruts: two polished tracks where the wheels ran ----
    const rut = cl(1-Math.abs(Math.abs(X)-.62)/.20, 0, 1)*wr;
    // ---- raking light from the two drifting pools ----
    const d1 = Math.sqrt((X-l1x)*(X-l1x) + (wz-zoff-l1z)*(wz-zoff-l1z));
    const d2 = Math.sqrt((X-l2x)*(X-l2x) + (wz-zoff-l2z)*(wz-zoff-l2z));
    const pool = Math.exp(-d1*d1*.10)*1.0 + Math.exp(-d2*d2*.07)*.75;
    // the dome normal points at the light -> the crown flares as a pool passes over it
    const toL = (l1x - X), toLz = (l1z - (wz-zoff));
    const nlen = Math.sqrt(toL*toL+toLz*toLz)+1e-3;
    const lamb = cl(.42 + (lx2*(toL/nlen) + ly2*(toLz/nlen))*-.55 + dome*.55, 0, 1);
    let lum = (.34 + q*.34) * (.54 + lamb*.70) * (1 + pool*glow*.62);
    lum *= 1 - jt*(.62 - rut*.18);                  // joints eat the light
    lum += rut*dome*(.16+glow*.22);                 // ruts are polished: they hold a sheen
    // granite grain + a little lichen/dirt in the low spots
    const grain = fbm(X*46+id*.7, wz*46)*det + (1-det)*.5;
    lum *= .82 + grain*.34;
    lum = cl(lum, 0, 1.4);
    let r = cSd[0]+(cSl[0]-cSd[0])*lum, g2 = cSd[1]+(cSl[1]-cSd[1])*lum, b2 = cSd[2]+(cSl[2]-cSd[2])*lum;
    // joint material (sand / moss) is a different colour, not just darker stone
    r += (cJt[0]-r)*jt*.72; g2 += (cJt[1]-g2)*jt*.72; b2 += (cJt[2]-b2)*jt*.72;
    if (moss){
      const mo = cl((fbm(X*7+3.1, wz*7)-.42)*3.0,0,1)*jt*(.4+wr*.8);
      r += (cJt[0]*1.3-r)*mo*.7; g2 += (cJt[1]*1.5-g2)*mo*.7; b2 += (cJt[2]*1.1-b2)*mo*.7;
    }
    if (wet){
      // standing water in the hollows: mirror-bright where a pool is behind you, and it
      // ripples — a broad live element across the whole plane
      const hollow = cl((jt*.7 + (1-dome)*.6 - .30)*1.8, 0, 1);
      const rip = .5+.5*Math.sin(wz*22 - tt*2.1 + X*7 + fbm(X*3, wz*3-tt*.4)*4.0);
      const spec = hollow*(.30+pool*glow*1.5)*(.55+rip*.75);
      r += (cRt[0]-r)*spec*.62; g2 += (cRt[1]-g2)*spec*.62; b2 += (cRt[2]-b2)*spec*.62;
    }
    if (bp){
      // setting-out plan: the arcs as cyan lines on a dark ground, no modelling at all
      const on = jt > .42 ? 1 : 0;
      const v2 = .12+.10*(1-far);
      r = on? 80 : v2*40; g2 = on? 200*det+36 : v2*100; b2 = on? 248 : v2*170;
    }
    // ---- aerial haze into the vanishing point, and the alpha falls off with it so the
    // floor dissolves into whatever bg sits behind, instead of ending in a hard line ----
    const hazeK = far*far*.85;
    const hc = bp? [40,120,190] : [cSl[0]*.72, cSl[1]*.72, cSl[2]*.78];
    r += (hc[0]-r)*hazeK; g2 += (hc[1]-g2)*hazeK; b2 += (hc[2]-b2)*hazeK;
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255);
    px[o+3] = 255*AL*cl(1-far*far*.72, 0, 1)*cl(dy/2.2, 0, 1);
  }
}
g.updatePixels();
push();
image(g,0,0,width,height);
pop();

// ---- a few crisp near setts along the bottom edge would alias badly on the upscale, so
// instead: wet-street sheen / dust drifting low over the stone, drawn crisp ----
push();
blendMode(ADD);
noStroke();
const dens = cl(P.density,0,1);
const NM = Math.round(6 + dens*40);
for (let i=0;i<NM;i++){
  const f1 = hsh(i*13+7, 3), f2 = hsh(i*13+8, 5), f3 = hsh(i*13+9, 11);
  // motes drift low across the plane, faster as they come toward the lens
  const mz = ((f2 + tt*(.02+f3*.07)*P.speed) % 1.05);
  const my = vy + Math.pow(mz,2.0)*(height-vy)*1.02;
  const mx = (f1 + Math.sin(tt*(.18+f3*.4)+f1*6.28)*.05)*width;
  const sz = u*(.0015+f3*.005)*(.4+mz*1.8);
  fill(wet?Hh-4:Hh+16, bp?40:16, 100, (7+f3*13)*(.3+en)*(P.alpha/100)*(1-mz*.4));
  ellipse(mx, my, sz, sz*.7);
}
blendMode(BLEND);
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
drawingContext.globalAlpha = 1;
